#include "contracts/ContractRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::contracts {bool ContractRuntime::publish(ContractInstance c){if(!c.stableId||!c.issuerStableId||c.objectives.empty()||contracts_.contains(c.stableId))return false;for(auto&o:c.objectives)if(!o.stableId||!o.required||!o.targetStableId)return false;contracts_[c.stableId]=std::move(c);return true;}bool ContractRuntime::objectivesComplete(const ContractInstance&c)const{return std::all_of(c.objectives.begin(),c.objectives.end(),[](auto&o){return o.progress>=o.required;});}
ContractResult ContractRuntime::apply(const ContractOperation&o){if(auto p=processed_.find(o.stableId);p!=processed_.end()){auto r=p->second;r.duplicate=true;return r;}ContractResult r;if(!o.stableId||!o.contractStableId){r.failure=ContractFailure::Invalid;return r;}auto i=contracts_.find(o.contractStableId);if(i==contracts_.end()){r.failure=ContractFailure::Invalid;return r;}auto&c=i->second;if(o.expectedRevision!=c.revision){r.failure=ContractFailure::RevisionConflict;return r;}if(c.deadlineTick&&o.tick>c.deadlineTick&&c.state==ContractState::Active){c.state=ContractState::Failed;c.revision=elysium::safe::saturatingIncrement(c.revision);r.committed=true;r.revision=c.revision;r.failure=ContractFailure::DeadlineExpired;if(!settled_[c.stableId]){r.events.push_back({c.stableId,c.state,false,{}});settled_[c.stableId]=true;}processed_[o.stableId]=r;return r;}switch(o.kind){case ContractOperation::Kind::Accept:if(c.state!=ContractState::Offered){r.failure=ContractFailure::WrongState;return r;}c.state=ContractState::Active;c.acceptedTick=o.tick;break;case ContractOperation::Kind::Progress:{if(c.state!=ContractState::Active){r.failure=ContractFailure::WrongState;return r;}auto oi=std::find_if(c.objectives.begin(),c.objectives.end(),[&](auto&x){return x.stableId==o.objectiveStableId;});if(oi==c.objectives.end()||oi->targetStableId!=o.targetStableId){r.failure=ContractFailure::TargetMismatch;return r;}oi->progress=std::min(oi->required,elysium::safe::saturatingAdd(oi->progress,o.amount));break;}case ContractOperation::Kind::Complete:if(c.state!=ContractState::Active||!objectivesComplete(c)){r.failure=ContractFailure::WrongState;return r;}c.state=ContractState::Completed;break;case ContractOperation::Kind::Fail:if(c.state!=ContractState::Active){r.failure=ContractFailure::WrongState;return r;}c.state=ContractState::Failed;break;case ContractOperation::Kind::Cancel:if(c.state!=ContractState::Offered&&c.state!=ContractState::Active){r.failure=ContractFailure::WrongState;return r;}c.state=ContractState::Cancelled;break;}c.revision=elysium::safe::saturatingIncrement(c.revision);r.committed=true;r.revision=c.revision;if(c.state==ContractState::Completed||c.state==ContractState::Failed||c.state==ContractState::Cancelled){if(!settled_[c.stableId]){r.events.push_back({c.stableId,c.state,c.state==ContractState::Completed,c.state==ContractState::Completed?c.rewards:std::vector<ContractReward>{}});settled_[c.stableId]=true;}}processed_[o.stableId]=r;return r;}
ContractResult ContractRuntime::expire(std::uint64_t id,std::uint64_t tick,std::uint64_t op){auto c=find(id);if(!c)return {};ContractOperation o{op,id,c->revision,tick,0,0,0,ContractOperation::Kind::Progress};return apply(o);}const ContractInstance*ContractRuntime::find(std::uint64_t id)const{auto i=contracts_.find(id);return i==contracts_.end()?nullptr:&i->second;}ContractSnapshot ContractRuntime::snapshot()const{ContractSnapshot s;for(auto&[_,c]:contracts_)s.contracts.push_back(c);for(auto&[id,_]:processed_)s.processedOperationIds.push_back(id);return s;}bool ContractRuntime::restore(const ContractSnapshot&s){ContractRuntime r;for(auto c:s.contracts){if(!c.stableId||r.contracts_.contains(c.stableId))return false;r.contracts_[c.stableId]=c;if(c.state==ContractState::Completed||c.state==ContractState::Failed||c.state==ContractState::Cancelled)r.settled_[c.stableId]=true;}for(auto id:s.processedOperationIds){if(!id||r.processed_.contains(id))return false;ContractResult x;x.committed=true;x.duplicate=true;r.processed_[id]=x;}*this=std::move(r);return true;}
} // namespace elysium::contracts
